python -c "
import pandas as pd,numpy as np
from scipy.optimize import curve_fit
d=pd.read_csv('spectrum.csv')
def L(x,a,c,w,b0,b1): return a*w**2/((x-c)**2+w**2)+b0+b1*(x-c)
for p in [104,206,242]:
  for c in ['parallel','crossed']:
    A=[]
    for ang,g in d[d.config==c].groupby('angle_deg'):
        g=g[(g.shift_cm1>p-18)&(g.shift_cm1<p+18)]
        try:
            q,_=curve_fit(L,g.shift_cm1,g.intensity,p0=[3000,p,3,900,0],bounds=([0,p-5,0.5,0,-50],[1e5,p+5,15,3000,50]),loss='soft_l1') if False else curve_fit(L,g.shift_cm1,g.intensity,p0=[3000,p,3,900,0])
            A.append((ang,round(q[0]),round(q[1],1),round(2*abs(q[2]),1)))
        except Exception as e: A.append((ang,None))
    print(p,c);print(A)
"

